    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

demo_output = G['Demo pair 1 output']
seed_r, seed_c = 4, 5

print("Output cells by Manhattan distance from seed (4,5):")
for dr in range(-4, 5):  # -1 to +5 actually
    for dc in range(-5, 6):
        r, c = seed_r + dr, seed_c + dc
        if 0 <= r < 11 and 0 <= c < 11:
            cell = demo_output[r][c]
            d1 = abs(dr) + abs(dc)
            print(f"({r:2d},{c:2d}): d={d1:2d}, val={cell}")

# Hmm this is too verbose. Let me group by d1
print("\n\nGrouped by distance d1:")
grouped = {}
for r in range(11):
    for c in range(11):
        d1 = abs(r-4) + abs(c-5)
        if d1 not in grouped:
            grouped[d1] = []
        grouped[d1].append((r,c,demo_output[r][c]))

for d1 in sorted(grouped.keys()):
    cells = grouped[d1]
    vals = [v for _,_,v in cells]
    if all(v == 0 for v in vals):
        print(f"d={d1:2d}: all 0")
    elif all(v == 1 for v in vals):
        print(f"d={d1:2d}: all 1 (3)")
    else:
        print(f"d={d1:2d}: mixed values: {vals[:5]}...")

